mapper.select:
SELECT id, start_date, end_date, event_time, title, memo, color_tag, is_hidden
FROM schedule_event
WHERE user_id = #{userId}
  AND start_date <= #{monthEnd}
  AND end_date >= #{monthStart}
ORDER BY start_date, event_time IS NULL, event_time, id

SELECT id, start_date, end_date, event_time, title, memo, color_tag, is_hidden
FROM schedule_event
WHERE id = #{id} AND user_id = #{userId}

SELECT id, start_date, end_date, event_time, title, memo, color_tag, is_hidden
FROM schedule_event
WHERE user_id = #{userId}
  AND start_date <= #{monthEnd}
  AND end_date >= #{monthStart}
  AND is_hidden = FALSE

      AND end_date >= #{sinceDate}


      AND start_date <= #{untilDate}

ORDER BY start_date, event_time IS NULL, event_time, id
